def try_fill_from_neighbors(in_grid, n):
    """Fill each zero position with first non-zero neighbor (up, right, down, left priority)"""
    out = [[in_grid[i][j] for j in range(n)] for i in range(n)]

    for i in range(n):
        for j in range(n):
            if out[i][j] == 0:
                # Try neighbors in order: left, up, right, down
                for di, dj in [(-1, 0), (0, -1), (1, 0), (0, 1)]:
                    ni, nj = (i + di) % n, (j + dj) % n
                    if in_grid[ni][nj] != 0:
                        out[i][j] = in_grid[ni][nj]
                        break
    return out

